import { Group, Mesh, MeshStandardNodeMaterial, PlaneGeometry, BoxGeometry, CylinderGeometry, RingGeometry, Vector3, Color, AdditiveBlending } from 'three/webgpu';
import { float, vec3, mix, time, uniform, positionWorld, normalWorld, uv, texture, clamp, length, normalize, dot, smoothstep, sin, cos, abs, pow, Fn } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const { ink, paper, accent, surface } = config.intent?.visualSpec?.colors || {};
  const colors = { ink: ink || '#16161d', paper: paper || '#e8ecf2', accent: accent || '#ff2a38', surface: surface || '#0b0b10' };

  // --- Load GLB mesh ---
  const meshGroup = new Group();
  let gearMesh = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene;
      scene.traverse((child) => {
        if (child.isMesh) {
          gearMesh = child;
          // Enhance PBR for machined metal look
          if (child.material) {
            child.material.metalness = 0.55;
            child.material.roughness = 0.5;
            child.material.clearcoat = 0.2;
            child.material.clearcoatRoughness = 0.3;
            child.material.envMapIntensity = 1.2;
            child.material.needsUpdate = true;
          }
        }
      });
      meshGroup.add(gltf.scene);
      group.add(meshGroup);
    });
  }

  // --- Stat tile card surface ---
  const cardGroup = new Group();
  const cardGeo = new BoxGeometry(1.2, 0.6, 0.08);
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
    envMapIntensity: 1.0
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.z = -0.04;
  cardGroup.add(cardMesh);

  // --- Beveled edge ring for machined detail ---
  const ringGeo = new RingGeometry(0.58, 0.62, 32);
  const ringMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    metalness: 0.3,
    roughness: 0.4,
    side: 2,
    transparent: true,
    opacity: 0.6
  });
  const ringMesh = new Mesh(ringGeo, ringMat);
  ringMesh.rotation.x = -Math.PI / 2;
  ringMesh.position.z = 0.045;
  cardGroup.add(ringMesh);

  // --- Value text (placeholder "42") ---
  const valueText = ctx.fontAtlas.createText('42', {
    fontSize: 0.34,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 0.02
  });
  valueText.position.set(0, 0.1, 0.06);
  cardGroup.add(valueText);

  // --- Label text ---
  const labelText = ctx.fontAtlas.createText('COLLECTION', {
    fontSize: 0.09,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 0.08
  });
  labelText.position.set(0, -0.12, 0.06);
  cardGroup.add(labelText);

  // --- Accent rim light (local) ---
  const rimLight = new Group();
  const rimGeo = new CylinderGeometry(0.7, 0.7, 0.02, 32, 1, true);
  const rimMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.8,
    transparent: true,
    opacity: 0.3,
    side: 2,
    blending: AdditiveBlending
  });
  const rimLightMesh = new Mesh(rimGeo, rimMat);
  rimLightMesh.rotation.x = Math.PI / 2;
  rimLightMesh.position.z = 0.05;
  cardGroup.add(rimLightMesh);

  // --- Contact shadow plane ---
  const shadowGeo = new PlaneGeometry(1.8, 1.8);
  const shadowMat = new MeshStandardNodeMaterial({
    color: new Color(0x000000),
    transparent: true,
    opacity: 0.4,
    side: 2,
    depthWrite: false
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.z = -0.1;
  cardGroup.add(shadowMesh);

  // --- Accent rim light (local) ---
  const accentLight = new Group();
  const lightGeo = new CylinderGeometry(0.65, 0.65, 0.01, 32, 1, true);
  const lightMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.2,
    transparent: true,
    opacity: 0.5,
    side: 2,
    blending: AdditiveBlending
  });
  const lightRing = new Mesh(lightGeo, lightMat);
  lightRing.rotation.x = Math.PI / 2;
  lightRing.position.z = 0.06;
  cardGroup.add(lightRing);

  // --- Key light (local) ---
  const keyLight = new Group();
  const keyGeo = new PlaneGeometry(0.8, 0.8);
  const keyMat = new MeshStandardNodeMaterial({
    color: new Color(colors.paper),
    emissive: new Color(colors.paper),
    emissiveIntensity: 0.6,
    transparent: true,
    opacity: 0.15,
    side: 2,
    blending: AdditiveBlending
  });
  const keyMesh = new Mesh(keyGeo, keyMat);
  keyMesh.position.set(0.5, 0.3, 0.08);
  keyMesh.rotation.x = -0.3;
  keyMesh.rotation.y = 0.4;
  cardGroup.add(keyMesh);

  // --- Rim light (back) ---
  const backRimGeo = new PlaneGeometry(1.4, 0.8);
  const backRimMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.6,
    transparent: true,
    opacity: 0.2,
    side: 2,
    blending: AdditiveBlending
  });
  const backRimMesh = new Mesh(backRimGeo, backRimMat);
  backRimMesh.position.set(0, 0, -0.08);
  backRimMesh.rotation.x = 0.2;
  cardGroup.add(backRimMesh);

  // --- Assemble card group ---
  cardGroup.add(meshGroup);
  group.add(cardGroup);

  // --- Apply cinematic primitives ---
  const primitives = config.cinematicPrimitives || [];
  const primitiveCleanups = [];

  for (const p of primitives) {
    if (ctx.primitives[p.name]) {
      const result = ctx.primitives[p.name](group, p.params);
      if (result && result.cleanup) {
        primitiveCleanups.push(result.cleanup);
      }
    }
  }

  // --- Entrance animation (weighted-settle) ---
  const entranceTL = gsap.timeline();
  cardGroup.scale.set(0, 0, 0);
  cardGroup.position.y = -0.4;
  entranceTL.to(cardGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
    overwrite: 'auto'
  });
  entranceTL.to(cardGroup.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  }, 0);

  // --- Hover interaction ---
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(cardGroup.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power2.out'
  }, 0);
  hoverTL.to(cardGroup.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 0.3,
    ease: 'power2.out'
  }, 0);

  // --- Click interaction ---
  const clickTL = gsap.timeline({ paused: true });
  clickTL.to(cardGroup.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(2)'
  });
  clickTL.to(cardGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.3,
    ease: 'power2.out'
  });

  // --- Event handlers ---
  group.userData.handlers = {
    pointerenter: () => {
      hoverTL.play();
    },
    pointerleave: () => {
      hoverTL.reverse();
    },
    click: () => {
      clickTL.restart();
      ctx.emit('navigate', { to: 'hub-collection' });
    }
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    entranceTL.kill();
    hoverTL.kill();
    clickTL.kill();
    primitiveCleanups.forEach(fn => fn());
    cardMat.dispose();
    cardGeo.dispose();
    ringMat.dispose();
    ringGeo.dispose();
    rimMat.dispose();
    rimGeo.dispose();
    shadowMat.dispose();
    shadowGeo.dispose();
    lightMat.dispose();
    lightGeo.dispose();
    keyMat.dispose();
    keyGeo.dispose();
    backRimMat.dispose();
    backRimGeo.dispose();
    if (gearMesh && gearMesh.material) {
      gearMesh.material.dispose();
    }
  };

  return group;
}
